    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    wall = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 4:
                if value == 2:
                    out[r][c] = 2
                continue
            nr = min(r + 1, h - 1)
            if wall is not None and r < wall and nr == wall - 1:
                out[nr][c] = 4
                for d in range(1, h):
                    rr = nr - d
                    if rr < 0:
                        break
                    for cc in (c - d, c + d):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
            else:
                out[nr][c] = 4
    return out

